	path, err := ClonePreferencesPath(ctx)
	if err != nil {
		return err
	}
	return modifyClonePreferencesFile(path, fn)
}

// LoadFromBytes parses settings from raw JSON bytes without merging local overrides.
// Use this when you have settings content from a non-file source (e.g., git show).
func LoadFromBytes(data []byte) (*EntireSettings, error) {
	s := &EntireSettings{Enabled: true}
	dec := json.NewDecoder(bytes.NewReader(data))
	dec.DisallowUnknownFields()
	if err := dec.Decode(s); err != nil {
		return nil, fmt.Errorf("parsing settings: %w", err)
	}
	if s.Redaction != nil {
		if err := validateOPFSettings(s.Redaction.OpenAIPrivacyFilter); err != nil {
			return nil, err
		}
	}
	return s, nil
}

// readConfined reads filePath through an os.Root, refusing outright to read it
// if it is a symbolic link.
//
// The root confines the open to its directory, so the read cannot be redirected
// outside it by a swapped or symlinked path between resolution and open
// (TOCTOU) — unlike a bare os.ReadFile of an absolute path. Callers must
// classify "missing" with errors.Is(err, fs.ErrNotExist) rather than
// os.IsNotExist, since the returned errors are wrapped.
//
// WHICH root is chosen by where the path is, not by whether an open succeeded:
// a path under .entire is read through the shared root every other .entire
// consumer uses, and a permission failure there must surface rather than
// silently retry through a second root. The other branch is not a weaker path
// but a different directory — this same function also reads clone preferences
// out of the git common dir, which .entire has no claim on.
//
// Confinement alone is NOT the invariant, which is why readConfinedIn also
// Lstats. Entire's config files are never read through a link, wherever it
// points, and os.Root leaves two gaps against that:
//
	fmt.Fprintln(w, formatSettingsStatusShort(ctx, effectiveSettings, sty))
	fmt.Fprintln(w) // blank line

	// Show project settings if it exists
	if projectExists {
		projectSettings, err := settings.LoadFromFile(settingsPath)
		if err != nil {
			return fmt.Errorf("failed to load project settings: %w", err)
		}
		fmt.Fprintln(w, formatSettingsStatus("Project", projectSettings, sty))
	}

	// An external_agents grant the loader refused. The user can see the
	// setting in their file and has no other way to learn it is inert:
	// discovery simply does not run, and the agent never appears.
	if reason, rejected := effectiveSettings.ExternalAgentsRejection(); rejected {
		fmt.Fprintf(w, "  external_agents is ignored: %s\n  move it to %s, and keep that file out of version control\n",
			reason, settings.EntireSettingsLocalFile)
	}

	// Show local settings if it exists. LoadFromFile is ungated, so this
	// renders the file's own contents — say so when the loader ignored them,
	// or the display contradicts the settings actually in effect.
	if localExists {
		localSettings, err := settings.LoadFromFile(localSettingsPath)
		if err != nil {
			return fmt.Errorf("failed to load local settings: %w", err)
		}
		label := "Local"
		if effectiveSettings.LocalLayerRejection() != "" {
			label = "Local (ignored)"
		}
		fmt.Fprintln(w, formatSettingsStatus(label, localSettings, sty))
		if reason := effectiveSettings.LocalLayerRejection(); reason != "" {
			fmt.Fprintf(w, "  %s\n  fix with: git rm --cached %s\n", reason, settings.EntireSettingsLocalFile)
		}
	}

	if effectiveSettings.Enabled {
		writeActiveSessions(ctx, w, sty)
	}
	writeAgentHelpHint(w, sty)

	return nil
}

