				fmt.Fprintf(w, "%s %s\n", sty.render(sty.yellow, "!"), sty.render(sty.yellow, warning))
			}
			fmt.Fprintln(w)
		}
	}

	// Footer: horizontal rule + session count
	fmt.Fprintln(w, sty.horizontalRule(sty.width))
	var footer string
	if totalSessions == 1 {
		footer = "1 session"
	} else {
		footer = fmt.Sprintf("%d sessions", totalSessions)
