	}
	metadata, err := gitrepo.ResolveWorktreeMetadata(worktreeRoot)
	if err != nil {
		return "", fmt.Errorf("resolve git common dir: %w", err)
	}
	gitDir := metadata.CommonDir
	if filepath.Base(gitDir) != ".git" {
		return "", fmt.Errorf("git common dir %q is not a .git directory", gitDir)
	}
	return filepath.Dir(gitDir), nil
}

// ensureTrailWorktreeIgnoreRule appends the .entire/worktrees/ rule to an
// existing repo-root .gitignore when the directory isn't already ignored.
// Already ignored, or no .gitignore at all → silent no-op: the CLI doesn't
// impose ignore policy on a repo that hasn't opted into one, and committing
// the appended rule stays the user's choice.
func ensureTrailWorktreeIgnoreRule(ctx context.Context, w io.Writer, root string) error {
	check := exec.CommandContext(ctx, "git", "check-ignore", "-q", trailWorktreesRelDir+"/")
	check.Dir = root
	err := check.Run()
	if err == nil {
		return nil
	}
	var exitErr *exec.ExitError
	if !errors.As(err, &exitErr) || exitErr.ExitCode() != 1 {
		return fmt.Errorf("failed to check ignore status of %s: %w", trailWorktreesRelDir, err)
	}

	appended, err := appendIgnoreRule(root)
	if err != nil {
		return err
	}
	if appended {
		fmt.Fprintln(w, "Added .entire/worktrees/ to .gitignore — commit it to keep the rule.")
	}
	return nil
}

func appendIgnoreRule(worktreeRoot string) (bool, error) {
	const rule = trailWorktreesRelDir + "/"
	const name = ".gitignore"
	// Through the worktree's root: .gitignore is a working-tree file, and the
	// tree arrives by clone. "derived from repo root" describes where the path
	// was built, not where it resolves.
	wt, err := worktreedir.OpenAt(worktreeRoot)
	if err != nil {
		return false, fmt.Errorf("failed to open worktree root: %w", err)
	}
	content, err := osroot.ReadFileNoFollow(wt, name)
	if errors.Is(err, os.ErrNotExist) {
		return false, nil
	}
	if err != nil {
		return false, fmt.Errorf("failed to read %s: %w", name, err)
	}
	for line := range strings.SplitSeq(string(content), "\n") {
		if strings.TrimSpace(line) == rule {
			return false, nil
		}
	}
	prefix := ""
	if len(content) > 0 && !strings.HasSuffix(string(content), "\n") {
		prefix = "\n"
	}
	updated := string(content) + prefix + rule + "\n"
	if err := jsonutil.WriteFileAtomicIn(wt, name, []byte(updated), 0o600); err != nil {
		return false, fmt.Errorf("failed to update %s: %w", name, err)
	}
	return true, nil
}

